import { useMemo } from 'react';

import type { ChartDataset, ChartOptions } from 'chart.js';
import {
  type BarChartData,
  DEFAULT_LINE_BAR_CHART_COLORS,
  getBarChartOptionsFromDatasets,
  getSeriesColorByLabel,
  type LineChartData,
} from 'components/Chart/lineBarChart';
import type {
  ComparisonLineData,
  ComparisonValue,
} from 'components/ComparisonLine';
import { theme } from 'theme';

import type { PhiOvertimeChartData } from '../../types';

export const PHI_LINE_CHART_Y_AXIS_WIDTH = 45;
export const PHI_LINE_CHART_LAYOUT_PADDING_TOP = 45;
export const PHI_LINE_CHART_GRID_COLOR = 'rgba(20, 20, 20, 0.08)';
const Y_GRID_BAND_HEIGHT = 45;
const Y_TICK_STEP = 20;
const X_AXIS_RESERVED_HEIGHT = 46;

const BUDGET_BAR_LABEL_PATTERN = /bu/i;

const PHI_BUDGET_BAR_STRIPED_PATTERN = {
  type: 'striped' as const,
  params: {
    color: '#FFFFFF',
    angle: 45,
    thickness: 1.5,
    spacing: 16,
  },
};

const LINE_LABEL_COLORS = [
  theme.colors.txt.secondary,
  theme.colors.txt.default,
] as const;

const PHI_CHART_DATA_LABEL_FONT = {
  size: 12,
  family: "'Work Sans', sans-serif",
  weight: 400 as const,
};

const PHI_BAR_CATEGORY_PERCENTAGE = 0.8;
const PHI_BAR_PERCENTAGE = 0.5;

const NEUTRAL_DASH_CELL: ComparisonValue = {
  value: '-',
  measure: '',
  color: '#5C5C5C',
  trend: 'neutral',
};

const PHI_ALWAYS_VISIBLE_LINE_LABEL_PATTERN = /budget|current/i;
const CURRENT_QUARTER_LINE_LABEL_PATTERN = /current/i;

type PhiDatalabelAnchor = 'end' | 'start' | 'center';
type PhiDatalabelSide = 'above' | 'below' | 'center';

type PhiLineDataset = {
  data: unknown[];
  hidden?: boolean;
};

type DatalabelContext = {
  datasetIndex: number;
  dataIndex: number;
};

const getLineChartYPlotHeight = (min: number, max: number) =>
  max <= min ? 0 : ((max - min) / Y_TICK_STEP) * Y_GRID_BAND_HEIGHT;

const getLineChartCanvasHeight = (min: number, max: number) =>
  PHI_LINE_CHART_LAYOUT_PADDING_TOP +
  getLineChartYPlotHeight(min, max) +
  X_AXIS_RESERVED_HEIGHT;

const getPhiLineChartDisplayLabels = (
  data: LineChartData,
): string[][] | undefined => {
  if (!data.datasets.length) {
    return undefined;
  }

  return data.datasets.map((dataset, datasetIndex) =>
    (data.labels ?? []).map((_, pointIndex) => {
      const formattedLabel = data.formattedData?.[datasetIndex]?.[pointIndex];

      if (formattedLabel != null && String(formattedLabel).trim() !== '') {
        return String(formattedLabel);
      }

      const rawValue = dataset.data[pointIndex];
      if (rawValue == null) {
        return '';
      }

      const numericValue = Number(rawValue);
      return Number.isFinite(numericValue) ? numericValue.toFixed(1) : '';
    }),
  );
};

const formatPhiAxisTick = (value: string | number): string => {
  const numericValue = Number(value);

  if (!Number.isFinite(numericValue)) {
    return '';
  }

  return String(Math.round(numericValue));
};

const isNeutralDashCell = (cell: ComparisonValue): boolean => {
  const value = String(cell.value ?? '').trim();
  return value === '-' && !cell.measure;
};

const formatPhiComparisonLineData = (
  data: ComparisonLineData[],
): ComparisonLineData[] =>
  data.map((line) => ({
    ...line,
    data: line.data.map((cell) =>
      isNeutralDashCell(cell) ? { ...NEUTRAL_DASH_CELL } : cell,
    ),
  }));

const getVisibleDatasets = (datasets: PhiLineDataset[]): PhiLineDataset[] =>
  datasets.filter((dataset) => !dataset.hidden);

const getVisibleValues = (
  datasets: PhiLineDataset[],
  dataIndex: number,
): number[] =>
  getVisibleDatasets(datasets)
    .map((dataset) => Number(dataset.data[dataIndex]))
    .filter((value) => !Number.isNaN(value));

const getPhiLineChartDatalabelSide = (
  context: DatalabelContext,
  datasets: PhiLineDataset[],
  displayLabels: string[][] | undefined,
): PhiDatalabelSide => {
  const currentDataset = datasets[context.datasetIndex];
  if (currentDataset?.hidden) {
    return 'center';
  }

  const { dataIndex } = context;
  const datasetsWithLabelAtPosition = (displayLabels ?? []).filter(
    (row) => row[dataIndex] != null && String(row[dataIndex]).trim() !== '',
  );

  let visibleValues: number[];

  if (datasetsWithLabelAtPosition.length <= 1) {
    const maxDataLength = Math.max(
      ...datasets.map((dataset) => dataset.data.length),
    );
    const isPartialSeries = currentDataset.data.length < maxDataLength;

    visibleValues = isPartialSeries
      ? currentDataset.data.map(Number).filter((value) => !Number.isNaN(value))
      : getVisibleValues(datasets, dataIndex);
  } else {
    visibleValues = getVisibleValues(datasets, dataIndex);
  }

  const currentValue = Number(currentDataset.data[dataIndex]);
  if (visibleValues.length === 0) {
    return 'center';
  }

  const max = Math.max(...visibleValues);
  const min = Math.min(...visibleValues);

  if (currentValue === max) {
    return 'above';
  }

  if (currentValue === min) {
    return 'below';
  }

  return currentValue - min >= max - currentValue ? 'below' : 'above';
};

const getPhiLineChartDatalabelAnchorAlign = (
  context: DatalabelContext,
  datasets: PhiLineDataset[],
  displayLabels: string[][] | undefined,
): PhiDatalabelAnchor => {
  const side = getPhiLineChartDatalabelSide(context, datasets, displayLabels);

  if (side === 'above') {
    return 'end';
  }

  if (side === 'below') {
    return 'start';
  }

  return 'center';
};

const getPhiLineChartDatalabelAnchor = (
  context: DatalabelContext,
  datasets: PhiLineDataset[],
  displayLabels: string[][] | undefined,
): PhiDatalabelAnchor =>
  getPhiLineChartDatalabelAnchorAlign(context, datasets, displayLabels);

const getPhiLineChartDatalabelAlign = (
  context: DatalabelContext,
  datasets: PhiLineDataset[],
  displayLabels: string[][] | undefined,
): PhiDatalabelAnchor => {
  const side = getPhiLineChartDatalabelSide(context, datasets, displayLabels);

  if (side === 'above') {
    return 'start';
  }

  if (side === 'below') {
    return 'end';
  }

  return 'center';
};

const shouldShowPhiLineChartLabel = (
  _datasets: PhiLineDataset[],
  displayLabels: string[][] | undefined,
  datasetIndex: number,
  dataIndex: number,
): boolean => {
  const label = displayLabels?.[datasetIndex]?.[dataIndex] ?? '';
  return String(label).trim() !== '';
};

const isPhiOvertimeAlwaysVisibleLineSeries = (label?: string): boolean =>
  PHI_ALWAYS_VISIBLE_LINE_LABEL_PATTERN.test(label?.trim() ?? '');

const isPhiOvertimeCurrentQuarterLineSeries = (label?: string): boolean =>
  CURRENT_QUARTER_LINE_LABEL_PATTERN.test(label?.trim() ?? '');

const getPlatformLineDatalabelAnchorOrAlign = (
  context: DatalabelContext,
  datasets: PhiLineDataset[],
  displayLabels: string[][] | undefined,
): PhiDatalabelAnchor => {
  const currentDataset = datasets[context.datasetIndex];
  if (currentDataset?.hidden) {
    return 'center';
  }

  const { dataIndex } = context;
  const datasetsWithLabelAtPosition = (displayLabels ?? []).filter(
    (row) => row[dataIndex] != null && String(row[dataIndex]).trim() !== '',
  );

  let visibleValues: number[];

  if (datasetsWithLabelAtPosition.length <= 1) {
    const maxDataLength = Math.max(
      ...datasets.map((dataset) => dataset.data.length),
    );
    const isPartialSeries = currentDataset.data.length < maxDataLength;

    visibleValues = isPartialSeries
      ? currentDataset.data.map(Number).filter((value) => !Number.isNaN(value))
      : getVisibleValues(datasets, dataIndex);
  } else {
    visibleValues = getVisibleValues(datasets, dataIndex);
  }

  const currentValue = Number(currentDataset.data[dataIndex]);
  if (visibleValues.length === 0) {
    return 'center';
  }

  const max = Math.max(...visibleValues);
  const min = Math.min(...visibleValues);

  if (currentValue === max) {
    return 'end';
  }

  if (currentValue === min) {
    return 'start';
  }

  return 'center';
};

const getBarBackgroundColors = (
  labels: string[],
  stripedIndexes: number[],
): string[] => {
  const { lastYear, budget, current } = DEFAULT_LINE_BAR_CHART_COLORS;

  return labels.map((label, index) => {
    if (stripedIndexes.includes(index)) {
      return budget ?? current;
    }

    if (BUDGET_BAR_LABEL_PATTERN.test(label)) {
      return budget ?? current;
    }

    if (/q\d/i.test(label)) {
      return current;
    }

    return lastYear;
  });
};

const buildPhiOvertimeLineDatasets = (
  lineChart: LineChartData,
): ChartDataset<'line'>[] => {
  const displayLabels = getPhiLineChartDisplayLabels(lineChart);
  const { datasets } = lineChart;

  return datasets.map((dataset, datasetIndex) => {
    const seriesColor = getSeriesColorByLabel(
      dataset.label,
      DEFAULT_LINE_BAR_CHART_COLORS,
    );

    const baseDataset: ChartDataset<'line'> = {
      ...dataset,
      borderColor: seriesColor,
      pointBackgroundColor: seriesColor,
      pointBorderColor: '#FFFFFF',
    };

    if (!isPhiOvertimeAlwaysVisibleLineSeries(dataset.label)) {
      return baseDataset;
    }

    const isCurrentQuarter = isPhiOvertimeCurrentQuarterLineSeries(
      dataset.label,
    );

    return {
      ...baseDataset,
      datalabels: {
        display: (context: DatalabelContext) =>
          shouldShowPhiLineChartLabel(
            datasets,
            displayLabels,
            context.datasetIndex,
            context.dataIndex,
          ),
        formatter: (_: unknown, context: DatalabelContext) => {
          const label =
            displayLabels?.[context.datasetIndex]?.[context.dataIndex] ?? '';
          return String(label).trim() || null;
        },
        anchor: (context: DatalabelContext) =>
          isCurrentQuarter
            ? getPhiLineChartDatalabelAnchor(context, datasets, displayLabels)
            : getPlatformLineDatalabelAnchorOrAlign(
                context,
                datasets,
                displayLabels,
              ),
        align: (context: DatalabelContext) =>
          isCurrentQuarter
            ? getPhiLineChartDatalabelAlign(context, datasets, displayLabels)
            : getPlatformLineDatalabelAnchorOrAlign(
                context,
                datasets,
                displayLabels,
              ),
        offset: 4,
        color: LINE_LABEL_COLORS[datasetIndex] ?? theme.colors.txt.default,
        font: PHI_CHART_DATA_LABEL_FONT,
      },
    };
  });
};

const buildPhiOvertimeBarDatasets = (
  barChart: BarChartData,
): ChartDataset<'bar'>[] => {
  const labels = barChart.labels ?? [];
  const stripedIndexes = barChart.stripedIndexes ?? [];
  const backgroundColors = getBarBackgroundColors(labels, stripedIndexes);

  return barChart.datasets.map((dataset) => ({
    ...dataset,
    backgroundColor: backgroundColors,
    borderColor: dataset.label
      ? getSeriesColorByLabel(dataset.label, DEFAULT_LINE_BAR_CHART_COLORS)
      : undefined,
    barThickness: 40,
    maxBarThickness: 40,
    barPercentage: PHI_BAR_PERCENTAGE,
    categoryPercentage: PHI_BAR_CATEGORY_PERCENTAGE,
    pattern: {
      ...PHI_BUDGET_BAR_STRIPED_PATTERN,
      flags: stripedIndexes,
    },
    datalabels: {
      font: PHI_CHART_DATA_LABEL_FONT,
      color: '#5C5C5C',
      anchor: 'end' as const,
      align: 'top' as const,
      offset: 6,
    },
  }));
};

export const usePhiLineBarChartDatasets = (data: PhiOvertimeChartData) => {
  const { lineChart, barChart } = data;

  const lineDatasets = useMemo(
    () => buildPhiOvertimeLineDatasets(lineChart),
    [lineChart],
  );

  const barDatasets = useMemo(
    () => buildPhiOvertimeBarDatasets(barChart),
    [barChart],
  );

  const comparisonData = useMemo(
    () => formatPhiComparisonLineData(lineChart.comparisonLine?.data ?? []),
    [lineChart.comparisonLine?.data],
  );

  const lineChartYMin = lineChart.suggestedMin ?? 0;
  const lineChartYMax = lineChart.suggestedMax ?? 100;

  const lineChartYPlotHeight = useMemo(
    () => getLineChartYPlotHeight(lineChartYMin, lineChartYMax),
    [lineChartYMin, lineChartYMax],
  );

  const lineChartCanvasHeight = useMemo(
    () => getLineChartCanvasHeight(lineChartYMin, lineChartYMax),
    [lineChartYMin, lineChartYMax],
  );

  const barOptions = useMemo((): ChartOptions<'bar'> => {
    const base = getBarChartOptionsFromDatasets(barChart.datasets);
    const baseYScale = base.scales?.y ?? {};
    const {
      min: baseYMin,
      max: baseYMax,
      ...baseYScaleWithoutBounds
    } = baseYScale;
    const yScaleMin =
      lineChart.suggestedMin ?? (typeof baseYMin === 'number' ? baseYMin : 0);
    const yScaleMax =
      lineChart.suggestedMax ?? (typeof baseYMax === 'number' ? baseYMax : 100);

    return {
      ...base,
      layout: {
        padding: {
          top: PHI_LINE_CHART_LAYOUT_PADDING_TOP,
          left: 0,
          right: 0,
          bottom: 0,
        },
      },
      plugins: {
        ...base.plugins,
        legend: { display: false },
        verticalGuidelines: {
          displayLeftY: false,
          displayRightY: false,
          displayAxisX: false,
          axisXLeftExtension: 0,
          axisXRightExtension: 0,
          color: PHI_LINE_CHART_GRID_COLOR,
        },
      },
      scales: {
        ...base.scales,
        x: {
          ...base.scales?.x,
          offset: true,
          grid: {
            display: false,
          },
          border: {
            ...base.scales?.x?.border,
            color: PHI_LINE_CHART_GRID_COLOR,
          },
        },
        y: {
          ...baseYScaleWithoutBounds,
          min: yScaleMin,
          max: yScaleMax,
          afterFit: (axis) => {
            axis.height = lineChartYPlotHeight;
          },
        },
      },
    };
  }, [
    barChart.datasets,
    lineChart.suggestedMax,
    lineChart.suggestedMin,
    lineChartYPlotHeight,
  ]);

  const lineChartOptions = useMemo(
    (): ChartOptions<'line'> => ({
      layout: {
        padding: {
          top: PHI_LINE_CHART_LAYOUT_PADDING_TOP,
          right: 0,
          bottom: 0,
        },
      },
      plugins: {
        legend: { display: false },
        customGrid: {
          display: true,
          color: PHI_LINE_CHART_GRID_COLOR,
          horizontalGridEnd: 'xAxisRight',
        },
        verticalGuidelines: {
          topExtension: PHI_LINE_CHART_LAYOUT_PADDING_TOP,
          displayLeftY: true,
          displayRightY: true,
          axisXLeftExtension: 0,
          axisXRightExtension: 0,
          color: PHI_LINE_CHART_GRID_COLOR,
        },
      },
      scales: {
        x: {
          offset: true,
          border: {
            display: false,
          },
        },
        y: {
          min: lineChartYMin,
          max: lineChartYMax,
          beginAtZero: true,
          ticks: {
            stepSize: Y_TICK_STEP,
            maxTicksLimit: 6,
            precision: 0,
            padding: 8,
            callback: (value) => formatPhiAxisTick(value),
          },
          afterFit: (axis) => {
            axis.width = PHI_LINE_CHART_Y_AXIS_WIDTH;
            axis.height = lineChartYPlotHeight;
          },
        },
      },
    }),
    [lineChartYMax, lineChartYMin, lineChartYPlotHeight],
  );

  return {
    lineChart,
    barChart,
    lineDatasets,
    barDatasets,
    barOptions,
    lineChartOptions,
    comparisonData,
    lineChartCanvasHeight,
  };
};
